patch:
Index: frontend/nuxt.config.ts
===================================================================
--- frontend/nuxt.config.ts	
+++ frontend/nuxt.config.ts	
@@ -1,21 +1,40 @@
 // Nuxt configuration for production build
 export default defineNuxtConfig({
+  srcDir: 'src',
   compatibilityDate: '2025-07-15',

+  app: {
+    head: {
+      title: 'مارکت‌فلو - هشدار هوشمند قیمت',
+      meta: [
+        { charset: 'utf-8' },
+        { name: 'viewport', content: 'width=device-width, initial-scale=1' },
+        { name: 'description', content: 'پلتفرم هشدار قیمت محصولات در ایران - ترب، دیوار و دیگر فروشگاه‌ها را پیگیری کنید' },
+        { name: 'keywords', content: 'قیمت محصولات, هشدار قیمت, ترب, دیوار, مارکت‌فلو' },
+        { property: 'og:title', content: 'مارکت‌فلو - هشدار هوشمند قیمت' },
+        { property: 'og:description', content: 'پلتفرم هشدار قیمت محصولات در ایران' },
+        { property: 'og:type', content: 'website' },
+      ],
+      link: [
+        { rel: 'canonical', href: 'https://marketflow.com' },
+      ],
+    }
+  },
+  
   modules: ['@pinia/nuxt', '@nuxtjs/tailwindcss'],

   runtimeConfig: {
     public: {
       apiBase: process.env.NUXT_PUBLIC_API_BASE || 'http://api.marketflow.local/api'
     }
   },

   // Preserve client/vite configuration
   vite: {
     build: {
       rollupOptions: {
         external: ['std-env', 'node-mock-http', 'uncrypto', 'iron-webcrypto']
       }
     }
   }
 })

