 async function loadHistory(watch: Watch) {
   if (!watch.history) watch.history = []
   watch.observations_loading = true
   try {
     const token = localStorage.getItem('auth_token')
     const page = watch.history_page || 1
     const resp = await $fetch(`/watches/${watch.id}/observations`, {
       baseURL: useRuntimeConfig().public.apiBase,
       headers: { Authorization: `Bearer ${token}` },
       query: { per_page: 10, page },
