   }
 }

 function toggleHistory(watchId: number) {
   showHistories[watchId] = !showHistories[watchId]
   if (showHistories[watchId]) {
     const watch = watches.value.find(w => w.id === watchId)
     if (watch && (!watch.history || watch.history.length === 0)) {
       loadHistory(watch)
     }
   }
 }

 function formatNumber(num: number): string {
   return num.toLocaleString('fa-IR')
 }

 onMounted(() => {
     demoLogin()
   })
 </script>

